function parseList(s){ return String(s).split(/[\s,;]+/).map(Number).filter(function(x){ return !isNaN(x); }); }
function mean(a){ if(!a.length) return NaN; var s=0; for(var i=0;i<a.length;i++) s+=a[i]; return s/a.length; }
function median(a){ if(!a.length) return NaN; var b=a.slice().sort(function(p,q){return p-q;}); var m=Math.floor(b.length/2); return b.length%2 ? b[m] : (b[m-1]+b[m])/2; }
function mode(a){ if(!a.length) return NaN; var f={}, best=0, bv=null; a.forEach(function(x){ f[x]=(f[x]||0)+1; if(f[x]>best){best=f[x]; bv=x;} }); return bv; }
function variance(a){ if(a.length<1) return NaN; var m=mean(a), s=0; for(var i=0;i<a.length;i++) s+=(a[i]-m)*(a[i]-m); return s/a.length; }
function stddev(a){ return Math.sqrt(variance(a)); }
function summary(a){ return {n:a.length, sum:a.reduce(function(p,c){return p+c;},0), min:Math.min.apply(null,a), max:Math.max.apply(null,a), mean:mean(a), median:median(a), mode:mode(a), variance:variance(a), stddev:stddev(a)}; }
var EXPORTS = { parseList:parseList, mean:mean, median:median, mode:mode, variance:variance, stddev:stddev, summary:summary };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StatisticsForgePure = EXPORTS; }
